import ctypes as c, os, subprocess, time
from pathlib import Path
from pywinauto import Desktop
import psutil

ROOT=Path(r"C:\dev\flyExplorer")
EXE=ROOT/"out"/"winui"/"Release"/"flyExplorer.exe"
profile=Path(os.environ["USERPROFILE"])
print("PROFILE",profile,flush=True)
print("PROFILE_CHILDREN",[(p.name,p.is_dir()) for p in sorted(profile.iterdir(), key=lambda x:x.name.lower())],flush=True)
for name in ("Desktop","Documents","Downloads","Pictures","Music","Videos"):
    p=profile/name
    print("PROFILE_CANDIDATE",name,repr(str(p)),"EXISTS",p.exists(),"DIR",p.is_dir(),flush=True)

# launch current Release with current VM environment, then only inspect UIA names
proc=subprocess.Popen([str(EXE),str(profile)],cwd=EXE.parent,env=os.environ.copy())
win=None
try:
    end=time.monotonic()+20
    while time.monotonic()<end:
        if proc.poll() is not None: break
        ws=[w for w in Desktop(backend="uia").windows(process=proc.pid) if "flyExplorer" in w.window_text()]
        if len(ws)==1:
            win=ws[0]; break
        time.sleep(.25)
    if not win:
        raise RuntimeError("flyExplorer window missing")
    time.sleep(3)
    pane=win.child_window(auto_id="LeftFiles")
    print("LEFTFILES_EXISTS",pane.exists(timeout=1),flush=True)
    rows=[]
    for item in pane.descendants():
        try:
            if item.element_info.control_type=="ListItem":
                rows.append(item.element_info.name or item.window_text())
        except Exception:
            pass
    print("FLY_UIA_ROW_COUNT",len(rows),flush=True)
    for x in rows[:80]:
        print("FLY_UIA_ROW",repr(x),flush=True)
finally:
    if proc.poll() is None:
        if win:
            c.windll.user32.PostMessageW(win.handle,0x10,0,0)
            try: proc.wait(timeout=8)
            except subprocess.TimeoutExpired:
                proc.terminate(); proc.wait(timeout=5)
        else:
            proc.terminate(); proc.wait(timeout=5)
print("EXIT",proc.returncode,flush=True)

